下面代码的输出是什么？

class Once:
    def __init__(self, func):
        self.func = func
        self.done = False
    def __call__(self, *a, **k):
        if not self.done:
            self.done = True
            return self.func(*a, **k)
        return None

@Once
def run():
    return 'run'

print(run(), run())

